html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
    {% if letter_head and not no_letterhead %}
        <div class="letter-head">{{ letter_head }}</div>
    {% endif %}
    {% if print_heading_template %}
        {{ frappe.render_template(print_heading_template, {"doc": doc}) }}
    {% endif %}
{%- endmacro -%}
<style>
    .letter-wrapper {
        font-family: 'Times New Roman', Times, serif;
        font-size: 12pt;
        line-height: 1.6;
        color: #000;
    }
    .letter-body {
        padding: 20px 40px;
    }
    .letter-date {
        text-align: right;
        margin-bottom: 20px;
    }
    .letter-recipient {
        margin-bottom: 20px;
    }
    .letter-subject {
        margin-bottom: 15px;
    }
    .letter-subject strong {
        text-decoration: underline;
    }
    .letter-content {
        text-align: justify;
        margin-bottom: 20px;
    }
    .status-cancelled {
        text-align: center;
        color: #991b1b;
        font-weight: bold;
        padding: 8px 0;
    }
    .status-draft {
        text-align: center;
        color: #92400e;
        font-weight: bold;
        padding: 8px 0;
    }
</style>
{% for page in layout %}
<div class="page-break letter-wrapper">
    <div {% if print_settings and print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
        {{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
    </div>
    {%- if doc.meta.is_submittable and doc.docstatus==2 -%}
        <div class="status-cancelled">{{ _("CANCELLED") }}</div>
    {%- endif -%}
    {%- if doc.meta.is_submittable and doc.docstatus==0 and (not print_settings or print_settings.add_draft_heading) -%}
        <div class="status-draft">{{ _("DRAFT") }}</div>
    {%- endif -%}
    <div class="letter-body">
        <div class="letter-date">
            {{ doc.get_formatted("date") }}
        </div>
        <div class="letter-recipient">
            {% if doc.recipient_name %}{{ doc.recipient_name }}<br>{% endif %}
            {% if doc.address_display %}{{ doc.address_display }}{% endif %}
        </div>
        {% if doc.subject %}
        <div class="letter-subject">
            <strong>{{ _("Subject") }}: {{ doc.subject }}</strong>
        </div>
        {% endif %}
        <div class="letter-content">
            {{ doc.content or "" }}
        </div>
    </div>
    {% if footer %}
    <div {% if print_settings and print_settings.repeat_header_footer %} id="footer-html" class="hidden-pdf" {% endif %}>
        {{ footer }}
    </div>
    {% endif %}
</div>
{% endfor %}
